public static void main(Args    _args)
{
    AVASpecialDiscQuotation sdq,nsdg;
    SalesQuotationTable       sqt;
    RecordInsertList         specDiscList = new RecordInsertList(tableNum(AVASpecialDiscQuotation));

    while select sqt
        notexists join nsdg
            where nsdg.QuotationId == sqt.QuotationId
    {
        sdq.QuotationId =    sqt.QuotationId;
        specDiscList.add(sdq);
    }
    specDiscList.insertDatabase();
}
